def maximize_power_discharge(M, S, steps):
    power = 1
    best_discharge = 0
    best_steps = steps
    max_mask = 1 << M

    for mask in range(max_mask):
        current_power = 1
        discharge = 0
        current_steps = list(steps)

        for i in range(M):
            if mask & (1 << i):
                current_steps[i] = 'o'
            else:
                if current_steps[i] == '+':
                    current_power += 1
                else:
                    current_power *= 2

            discharge = max(discharge, current_power % (1 << S))

        if discharge > best_discharge:
            best_discharge = discharge
            best_steps = ''.join(current_steps)

    return best_steps

